struct Data { int value = 1; };

// Initial owner
std::unique_ptr<Data> p_source =
    std::make_unique<Data>();

// Transfer ownership via move assignment
std::unique_ptr<Data> p_dest = std::move(p_source);

// p_source is now nullptr

void process(std::unique_ptr<Data> resource) {
    // resource owns the Data object locally
}

// Transfer ownership to a function parameter
process(std::move(p_dest));

// p_dest is now nullptr
// Data object destroyed when process returns
// (Exclusive ownership guarantee)
